// @ts-check
// Criaturas do Mundo (creatures): the first official content mod — original creatures that belong to the world's places
// instead of the zombie/skeleton cliché. v1: the Moss Lurker (Espreitador do Musgo), a forest ambusher.
// This is the CONTENT entry (it runs on the server and in the browser, so both get the same ids): sounds, textures,
// the Moss Hide item and its recipe, the spawn condition and the mob. The browser-only glow of its eyes is src/client.ts.
// Public SDK only; every asset is generated by tools/gen-assets.ts.
import { MOB_PATH } from './anatomy.ts';
import MossLurker from './lurker.ts';
import { OVERWORLD, forestFloor, inOpenOverworld } from './spawn.ts';
import { registerGoblin } from '../goblin/index.ts';
import { registerWidow } from '../widow/index.ts';
import { registerBeetle } from '../beetle/index.ts';
import { registerLantern } from '../lantern/index.ts';
import { registerSentinel } from '../sentinel/index.ts';
import { registerSwarm } from '../swarm/index.ts';
import { registerSerpent } from '../serpent/index.ts';
import { registerColossus } from '../colossus/index.ts';
import { registerHermit } from '../hermit/index.ts';
import { registerStructures } from '../structures/index.ts';
import { registerOutposts } from '../structures/watchtower/index.ts';
import { registerRuinedCastle } from '../structures/ruined_castle/index.ts';
import { registerFolk } from '../folk/index.ts';

export const SOUND_NAMES = ['rustle', 'hiss', 'leap', 'bite', 'hurt', 'death'];

/** @param {any} ctx */
export default function register(ctx) {
  // its voice, from code-synthesized files (sfx: at most 4 s and 256 KB each)
  for (const name of SOUND_NAMES) ctx.sounds.file(`${MOB_PATH}_${name}`, `sounds/${MOB_PATH}/${name}.wav`);
  const sound = (name) => `creatures:${MOB_PATH}_${name}`;

  // the drop: Moss Hide, and a cheap use for it (two hides tan into one leather)
  ctx.textures.png('moss_hide', 'textures/items/moss_hide.png', { size: 16 });
  ctx.items.register('moss_hide', { name: 'Couro de Musgo', icon: 'creatures:moss_hide', group: 'mineclaude:items',
    lore: [ctx.lang.text('item.moss_hide.lore1', undefined, 'Pele de um Espreitador do Musgo.'), ctx.lang.text('item.moss_hide.lore2', undefined, 'Ainda cheira a floresta molhada.')] });
  ctx.recipes.add({ key: 'leather_from_moss_hide', out: 'mineclaude:leather', n: 1, in: [['creatures:moss_hide', 2]] });

  // The world, for the spawn test: read lazily (only the server draws spawns; ctx.dimensions.world exists only there).
  let world = null;
  const getBlock = (pos) => {
    try { world ??= ctx.dimensions.world(OVERWORLD); return world.getBlock(pos); } catch { return null; }
  };
  // a forest floor by day: the 'day' situation (grass under open sky) with the same under-the-trees test
  ctx.mobs.spawnCondition('forest_day', { situation: 'day', test: forestFloor(getBlock) });
  // by day inside a creature's HOME biome (src/biome-homes.ts): only the guards, the biome filter is on the rule
  ctx.mobs.spawnCondition('home_day', { situation: 'day', test: inOpenOverworld });
  ctx.mobs.register(MOB_PATH, new MossLurker({ getBlock, sound }));

  // the Goblin (goblin/): its sounds, pebble, items and mob
  registerGoblin(ctx);
  // the Dune Widow (widow/): its sounds, sand, venom, items, desert spawn and mob
  registerWidow(ctx);
  registerBeetle(ctx); // the Crystal Beetle (beetle/): its sounds, shard and mob
  // the Lure Lantern (lantern/): its sounds, the Glow Gland and the mob
  registerLantern(ctx);
  registerSentinel(ctx); // the Canopy Sentinel (sentinel/)
  registerSwarm(ctx); // the Sting Swarm (swarm/)
  registerSerpent(ctx); // the Root Serpent (serpent/)
  registerColossus(ctx); // the Ruin Colossus (colossus/)
  registerHermit(ctx); // the Tide Hermit (hermit/)
  registerStructures(ctx); // the abandoned village and the goblin camp, our mobs' homes (structures/)
  registerOutposts(ctx); // the Watchtower and the Forgotten Shrine (structures/watchtower/): new worlds with biomes only
  registerRuinedCastle(ctx); // the Ruined Castle (structures/ruined_castle/): its blocks, loot, generator stage and home spawns
  registerFolk(ctx); // the Musgarretes (folk/): living NPCs on ctx.npcs — their blocks, village stage, jobs, trades, moving-in
}
